package com.saasquatch.intelligence.controller;
import com.saasquatch.intelligence.dto.*;import com.saasquatch.intelligence.repository.*;import com.saasquatch.intelligence.service.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/opportunities") @CrossOrigin(origins="*") public class OpportunityController{final LeadRepository leads;final ScoringService scoring;final CorporateRelationshipService rels;public OpportunityController(LeadRepository l,ScoringService s,CorporateRelationshipService r){leads=l;scoring=s;rels=r;}@GetMapping("/top") public List<LeadIntelligenceResponse> top(){return leads.findAll().stream().map(l->scoring.intelligence(l,rels.forCompany(l.getCompany().getId()))).sorted(Comparator.comparingInt(LeadIntelligenceResponse::opportunityScore).reversed()).limit(10).toList();}}